import{_ as o,a0 as r,w as l,s as d,ao as s,I as a,x as n,a1 as i,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"实测 Linux Mint 升级工具 | LCTT x X-CMD","titleTemplate":false,"description":"实测 Linux Mint 升级工具 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"实测 Linux Mint 升级工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"实测 Linux Mint 升级工具 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220425 Linux Mint Upgrade Tool - Here-s How it Works","title":"实测 Linux Mint 升级工具","tag":"202205","desc":""},"relativePath":"202205/20220425 Linux Mint Upgrade Tool - Here-s How it Works.md","filePath":"[post].md"}'),u={name:"202205/20220425 Linux Mint Upgrade Tool - Here-s How it Works.md"};function g(m,t,x,w,h,b){const e=r("Link");return l(),d("div",null,[t[20]||(t[20]=s('<h1 id="实测-linux-mint-升级工具" tabindex="-1">实测 Linux Mint 升级工具 <a class="header-anchor" href="#实测-linux-mint-升级工具" aria-label="Permalink to “实测 Linux Mint 升级工具”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/01/170956n81yky0l8vbvy1n8.jpg" alt=""></p><blockquote><p>我们通过实际升级测试了 Linux Mint 升级工具（mintupgrade GUI）。这是我们的发现。</p></blockquote><p>这个工具正在开发中，可能包含错误，除非你想实验一下，否则请不要在你的日常中使用它。</p><h3 id="linux-mint-升级工具" tabindex="-1">Linux Mint 升级工具 <a class="header-anchor" href="#linux-mint-升级工具" aria-label="Permalink to “Linux Mint 升级工具”">​</a></h3>',5)),a("p",null,[t[1]||(t[1]=n("Linux Mint 团队 ",-1)),i(e,{href:"https://www.debugpoint.com/2022/04/linux-mint-21-announcement/"},{default:p(()=>[...t[0]||(t[0]=[n("宣布",-1)])]),_:1}),t[2]||(t[2]=n("，他们建立了一个新的工具来升级 Linux Mint 的主要版本。它被称为 “mintupgrade2”。它目前正在开发中，计划用于升级主要版本。例如，从 Linux Mint 20 到 21，而不是小版本的升级。",-1))]),t[21]||(t[21]=s(`<p>虽然你可以使用标准的 <code>apt</code> 命令来升级版本，然而，Mint 团队认为主要版本的升级是很棘手的。新用户很难顺利升级，因为它涉及到终端和一套复杂的命令步骤。</p><p>此外，这个图形用户界面是对 mintupgrade 程序的封装，并带有一些附加功能，它带来了一套系统前检查和一键修复的升级过程。</p><p>除此之外，mintupgrade 还会检查你是否连接到电源、系统是否是最新的、磁盘空间的可用性等等。</p><p>为了让大家了解它的外观和工作情况，我们使用 LMDE 4 设置了一个测试平台做了个测试。</p><p>但在这之前，让我快速介绍一下它的功能：</p><ul><li>完全由 GUI 驱动的升级过程</li><li>多语言支持</li><li>升级前检查：系统备份、电源、磁盘空间、删除的软件包列表</li><li>可配置</li><li>提醒你来自上一个版本的孤儿软件包</li><li>给你修复问题的选项</li></ul><h3 id="它是如何工作的" tabindex="-1">它是如何工作的 <a class="header-anchor" href="#它是如何工作的" aria-label="Permalink to “它是如何工作的”">​</a></h3><p>当我们通过命令 <code>mintupgrade</code> 运行这个 Mint 升级工具时，这个图形用户界面程序友好的欢迎屏幕是一个很好的起点，它开启了升级过程，然后它自己开始进行一系列的检查。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Starting-the-upgrade-process.jpg" alt="Starting the upgrade process"></p><p>除此之外，当它在你的系统中发现一些问题时，它会停下来并给你足够的细节。当你点击“修复”后，它就可以再次恢复进程。</p><p>不止如此。如果由于网络或互联网或任何其他问题而中断，它也可以恢复升级过程。</p><p>在我们的测试过程中，该工具在我们的测试系统中发现了以下错误，只需点击一下就能修复它们。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Apt-Cache-check-1024x521.jpg" alt="Apt Cache check"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Mint-Upgrade-detects-that-system-snapshots-not-present-1024x522.jpg" alt="Mint Upgrade detects that system snapshots are not present"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Check-for-Orphan-Packages-1024x522.jpg" alt="Check for Orphan Packages"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Status-before-upgrade-1024x528.jpg" alt="Status before upgrade"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Mint-Upgrade-can-detect-the-packages-require-downgrade-1024x612.jpg" alt="Mint Upgrade can detect the packages that require a downgrade"></p><p>最后，我们成功地将一个测试系统从 LMDE 4 升级到 LMDE 5。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Upgrade-Complete-1024x612.jpg" alt="Upgrade Complete"></p><h4 id="如何获得这个升级工具" tabindex="-1">如何获得这个升级工具 <a class="header-anchor" href="#如何获得这个升级工具" aria-label="Permalink to “如何获得这个升级工具”">​</a></h4><p>使用下面的命令，该工具的安装很简单。但正如该团队所建议的，它现在处于 BETA 状态，所以不要用它来进行正式场合的升级。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install mintupgrade</span></span></code></pre></div><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to “结束语”">​</a></h3><p>最后，我认为这是 Linux Mint 团队的最好的工具之一。正如你在上面看到的，它自己处理了许多错误。我所做的只是点击“修复”按钮。而这个工具足够聪明，能够理解所有的故障点，并负责补救。</p>`,24)),a("p",null,[i(e,{href:"https://github.com/linuxmint/mintupgrade"},{default:p(()=>[...t[3]||(t[3]=[n("mintupgrade 工具",-1)])]),_:1}),t[4]||(t[4]=n(" 将在 Linux Mint 21 “Vanessa” 发布前发布，大约在 2022 年第三季度末或第四季度初。",-1))]),t[22]||(t[22]=a("hr",null,null,-1)),a("p",null,[t[6]||(t[6]=n("via: ",-1)),i(e,{href:"https://www.debugpoint.com/2022/04/mint-upgrade-tool/"},{default:p(()=>[...t[5]||(t[5]=[n("https://www.debugpoint.com/2022/04/mint-upgrade-tool/",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=n("作者：",-1)),i(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:p(()=>[...t[7]||(t[7]=[n("Arindam",-1)])]),_:1}),t[12]||(t[12]=n(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:p(()=>[...t[8]||(t[8]=[n("lujun9972",-1)])]),_:1}),t[13]||(t[13]=n(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:p(()=>[...t[9]||(t[9]=[n("geekpi",-1)])]),_:1}),t[14]||(t[14]=n(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[10]||(t[10]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[17]||(t[17]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[15]||(t[15]=[n("LCTT",-1)])]),_:1}),t[18]||(t[18]=n(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:p(()=>[...t[16]||(t[16]=[n("Linux中国",-1)])]),_:1}),t[19]||(t[19]=n(" 荣誉推出",-1))])])}const L=o(u,[["render",g]]);export{T as __pageData,L as default};
